style.css:
@-moz-document domain("youtube.com") {
/* =========================================================
       1. 2008 EDGY NEON PINK SUBSCRIBE BUTTON
       ========================================================= */
    ytd-subscribe-button-renderer button,
    yt-subscribe-button-view-model button,
    #subscribe-button button,
    .yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono {
        background-color: #ff007f !important;
        background-image: linear-gradient(180deg, #ff4da6 0%, #ff007f 50%, #cc0066 100%) !important;
        color: #000000 !important;
        border: 2px solid #000000 !important;
        border-radius: 4px !important;
        box-shadow: 0 0 10px #ff007f, inset 0 1px 0 rgba(255, 255, 255, 0.6) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 18px !important;
        font-weight: 400 !important;
        letter-spacing: 2px !important;
        text-transform: uppercase !important;
        transition: all 0.15s ease-in-out !important;
    }

    ytd-subscribe-button-renderer button .yt-core-attributed-string,
    yt-subscribe-button-view-model button .yt-core-attributed-string,
    #subscribe-button button span {
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        color: #000000 !important;
        text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.4) !important;
    }

    ytd-subscribe-button-renderer button:hover,
    yt-subscribe-button-view-model button:hover,
    #subscribe-button button:hover {
        background-color: #ff3399 !important;
        background-image: linear-gradient(180deg, #ff80bf 0%, #ff1a8c 50%, #e60073 100%) !important;
        box-shadow: 0 0 18px #ff007f, 0 0 5px #ffffff !important;
        transform: scale(1.03) !important;
    }

    ytd-subscribe-button-renderer[subscribed] button,
    .yt-spec-button-shape-next--tonal.yt-spec-button-shape-next--mono {
        background-color: #1a1a1a !important;
        background-image: none !important;
        color: #ff007f !important;
        border: 2px solid #ff007f !important;
        box-shadow: 0 0 8px rgba(255, 0, 127, 0.5) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 18px !important;
        letter-spacing: 2px !important;
    }

    ytd-subscribe-button-renderer[subscribed] button .yt-core-attributed-string,
    .yt-spec-button-shape-next--tonal.yt-spec-button-shape-next--mono .yt-core-attributed-string {
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        color: #ff007f !important;
        text-shadow: none !important;
    }

    /* =========================================================
       2. 2008 EDGY SCENE NEON LIKE & DISLIKE BUTTONS
       ========================================================= */
    like-button-view-model button,
    dislike-button-view-model button,
    segmented-like-dislike-button-view-model button,
    #segmented-like-button button,
    #segmented-dislike-button button {
        background-color: #0d0d0d !important;
        background-image: linear-gradient(180deg, #333333 0%, #111111 50%, #000000 100%) !important;
        color: #ff007f !important;
        border: 2px solid #ff007f !important;
        border-radius: 4px !important;
        box-shadow: 0 0 8px rgba(255, 0, 127, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.35) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 16px !important;
        letter-spacing: 1.5px !important;
        transition: all 0.15s ease-in-out !important;
    }

    like-button-view-model button {
        margin-right: 4px !important;
    }

    like-button-view-model button .yt-core-attributed-string,
    segmented-like-dislike-button-view-model button .yt-core-attributed-string,
    like-button-view-model svg,
    dislike-button-view-model svg {
        color: #ff007f !important;
        fill: #ff007f !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
    }

    /* LIKE HOVER & ACTIVE -> Electric 2008 Scene Lime Green */
    like-button-view-model button:hover,
    #segmented-like-button button:hover,
    like-button-view-model button[aria-pressed="true"],
    #segmented-like-button button[aria-pressed="true"] {
        background-color: #0a1f0a !important;
        background-image: linear-gradient(180deg, #1f4d1f 0%, #0d260d 50%, #051405 100%) !important;
        border-color: #39ff14 !important;
        color: #39ff14 !important;
        box-shadow: 0 0 15px #39ff14, inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
        transform: translateY(-1px) !important;
    }

    like-button-view-model button:hover .yt-core-attributed-string,
    like-button-view-model button[aria-pressed="true"] .yt-core-attributed-string,
    like-button-view-model button:hover svg,
    like-button-view-model button[aria-pressed="true"] svg {
        color: #39ff14 !important;
        fill: #39ff14 !important;
    }

    /* DISLIKE HOVER & ACTIVE -> Cyber Crimson / Blood Red */
    dislike-button-view-model button:hover,
    #segmented-dislike-button button:hover,
    dislike-button-view-model button[aria-pressed="true"],
    #segmented-dislike-button button[aria-pressed="true"] {
        background-color: #26050d !important;
        background-image: linear-gradient(180deg, #590d1f 0%, #2b050e 50%, #140206 100%) !important;
        border-color: #ff003c !important;
        color: #ff003c !important;
        box-shadow: 0 0 15px #ff003c, inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
        transform: translateY(-1px) !important;
    }

    dislike-button-view-model button:hover svg,
    dislike-button-view-model button[aria-pressed="true"] svg {
        color: #ff003c !important;
        fill: #ff003c !important;
    }
}
